export type DigitalTwinProjectMode = 'operational' | 'construction';

export type EnergyMetric = {
  label: string;
  value: string;
  helper: string;
};

export type ConstructionMilestone = {
  id: string;
  label: string;
  completed: boolean;
};

export type DigitalTwinProject = {
  id: string;
  title: string;
  statusLabel: string;
  mode: DigitalTwinProjectMode;
  modelUrl: string;
  modelFormat: 'glb' | 'gltf';
  modelNotes: string;
  energyMetrics?: EnergyMetric[];
  milestones?: ConstructionMilestone[];
};

// TODO: replace hardwired digital twin project config with database-backed project/model records.
export const digitalTwinProjects: Record<string, DigitalTwinProject> = {
  '1': {
    id: '1',
    title: 'Cornwall Wind turbine Pilot #1',
    statusLabel: 'Operational',
    mode: 'operational',
    modelUrl: '/models/digital-twin/wind-turbine/Wind-turbine.glb',
    modelFormat: 'glb',
    modelNotes:
      'This GLB is suitable for MVP rendering, but currently appears to be one merged mesh without stable per-element IDs.',
    // TODO: replace generated operational metrics with database-backed sensor readings.
    energyMetrics: [
      { label: 'Past day', value: '8.4 MWh', helper: '+6.2% vs previous day' },
      { label: 'Past week', value: '57.8 MWh', helper: '92% availability' },
      { label: 'Current month', value: '214.6 MWh', helper: 'On track for target' },
      { label: 'Past month', value: '248.2 MWh', helper: 'Peak output 1.8 MW' },
    ],
  },
  '2': {
    id: '2',
    title: 'Cornwall Wind turbine Pilot #2',
    statusLabel: 'Construction',
    mode: 'construction',
    modelUrl: '/models/digital-twin/wind-turbine/Wind_Turbine 2.gltf',
    modelFormat: 'gltf',
    modelNotes:
      'This glTF has multiple nodes and meshes, but names are generic or duplicated and need stable provider IDs before robust status mapping.',
    // TODO: replace local milestone state with persisted construction status data.
    milestones: [
      { id: 'concrete-foundation', label: 'concrete foundation', completed: true },
      { id: 'tower-lower-sections', label: 'tower lower sections', completed: true },
      { id: 'tower-higher-section', label: 'tower higher section', completed: false },
      { id: 'generator', label: 'generator', completed: false },
      { id: 'blade-1', label: 'blade 1', completed: false },
      { id: 'blade-2', label: 'blade 2', completed: false },
      { id: 'blade-3', label: 'blade 3', completed: false },
    ],
  },
};

export function getDigitalTwinProject(id: string) {
  return digitalTwinProjects[id];
}

'use client';

import { Bounds, Center, Html, OrbitControls, useGLTF } from '@react-three/drei';
import { Canvas } from '@react-three/fiber';
import { Suspense } from 'react';

type DigitalTwinModelViewerProps = {
  modelUrl: string;
  title: string;
};

function Model({ modelUrl }: { modelUrl: string }) {
  const gltf = useGLTF(modelUrl);

  return (
    <Center>
      <primitive object={gltf.scene} />
    </Center>
  );
}

function LoadingModel() {
  return (
    <Html center>
      <div className="rounded-full border border-card-border bg-[#0C0C0D]/90 px-4 py-2 text-sm text-gray-200 shadow-xl">
        Loading 3D model…
      </div>
    </Html>
  );
}

export function DigitalTwinModelViewer({
  modelUrl,
  title,
}: DigitalTwinModelViewerProps) {
  return (
    <section className="overflow-hidden rounded-[28px] border border-card-border bg-card-bg shadow-2xl backdrop-blur-xl">
      <div className="flex flex-col gap-1 border-b border-card-border px-6 py-5 md:flex-row md:items-center md:justify-between">
        <div>
          <p className="text-xs uppercase tracking-[0.35em] text-primary">
            AI-Digital Twin
          </p>
          <h1 className="chakra-petch mt-2 text-3xl font-bold text-white md:text-4xl">
            {title}
          </h1>
        </div>
        <p className="max-w-sm text-sm leading-6 text-gray-300">
          Orbit, pan, and zoom the turbine model. Element-level status overlays
          will plug into this viewer once stable model IDs are available.
        </p>
      </div>

      <div className="h-[520px] bg-[radial-gradient(circle_at_50%_25%,rgba(36,255,142,0.16),transparent_32%),linear-gradient(180deg,rgba(21,30,47,0.75),rgba(12,12,13,0.95))]">
        <Canvas camera={{ position: [5, 4, 8], fov: 45 }} shadows>
          <color attach="background" args={['#0C0C0D']} />
          <ambientLight intensity={1.4} />
          <directionalLight position={[5, 8, 6]} intensity={2.6} castShadow />
          <pointLight position={[-5, 4, -5]} intensity={1.2} color="#24FF8E" />
          <Suspense fallback={<LoadingModel />}>
            <Bounds fit clip observe margin={1.35}>
              <Model modelUrl={modelUrl} />
            </Bounds>
          </Suspense>
          <OrbitControls makeDefault enableDamping dampingFactor={0.08} />
        </Canvas>
      </div>
    </section>
  );
}

'use client';

import { useMemo, useState } from 'react';
import type { ConstructionMilestone } from '@/lib/digital-twin-projects';

type MilestoneChecklistProps = {
  milestones: ConstructionMilestone[];
};

export function MilestoneChecklist({ milestones }: MilestoneChecklistProps) {
  const [items, setItems] = useState(milestones);
  const completedCount = useMemo(
    () => items.filter((item) => item.completed).length,
    [items],
  );
  const progress = Math.round((completedCount / items.length) * 100);

  return (
    <section className="rounded-[24px] border border-card-border bg-card-bg p-6 backdrop-blur-xl">
      <div className="mb-6 flex flex-col gap-4 md:flex-row md:items-end md:justify-between">
        <div>
          <p className="text-xs uppercase tracking-[0.3em] text-primary">
            Construction milestones
          </p>
          <h2 className="chakra-petch mt-2 text-2xl font-bold text-white">
            Build status checklist
          </h2>
        </div>
        <div className="text-right text-sm text-gray-300">
          <p>
            {completedCount} of {items.length} complete
          </p>
          <p className="text-primary">{progress}% progress</p>
        </div>
      </div>

      <div className="mb-6 h-2 overflow-hidden rounded-full bg-[#0C0C0D]">
