          <color
            attach="background"
            args={[showGroundPlane ? '#6f6f6f' : '#808080']}
          />
          <ambientLight intensity={0.35} />
          <hemisphereLight args={['#ffffff', '#303030', 0.7]} />
          {showKeyLight ? (
            <directionalLight
              position={[45, 90, 45]}
              intensity={4.8}
              castShadow
              shadow-mapSize={[4096, 4096]}
              shadow-camera-near={1}
              shadow-camera-far={180}
              shadow-camera-left={-90}
              shadow-camera-right={90}
              shadow-camera-top={90}
              shadow-camera-bottom={-90}
              shadow-bias={-0.0002}
              shadow-normalBias={0.08}
            />
          ) : null}
          <pointLight position={[-5, 4, -5]} intensity={0.6} color="#24FF8E" />
          <Environment preset="city" environmentIntensity={0.45} />
          <Suspense fallback={<LoadingModel />}>
            <Bounds clip margin={1.35}>
              <group>
                {showGroundPlane ? (
                  <group position={[0, 0, 0]}>
                    <gridHelper args={[76, 38, '#d8d8d8', '#a8a8a8']} />
                    <mesh
                      rotation={[-Math.PI / 2, 0, 0]}
                      position={[0, -0.01, 0]}
                      receiveShadow
                    >
                      <planeGeometry args={[76, 76]} />
                      <meshStandardMaterial color="#505050" roughness={0.95} />
                    </mesh>
                  </group>
                ) : null}
                <Model modelUrl={modelUrl} />
              </group>
            </Bounds>
          </Suspense>
          <OrbitControls makeDefault enableDamping dampingFactor={0.08} />
        </Canvas>
      </div>
    </section>
  );
}

'use client';

import { useMemo, useState } from 'react';
import type { ConstructionMilestone } from '@/lib/digital-twin-projects';

type MilestoneChecklistProps = {
  milestones: ConstructionMilestone[];
};

export function MilestoneChecklist({ milestones }: MilestoneChecklistProps) {
  const [items, setItems] = useState(milestones);
  const completedCount = useMemo(
    () => items.filter((item) => item.completed).length,
    [items]
  );
  const progress = Math.round((completedCount / items.length) * 100);

  return (
    <section className="rounded-[24px] border border-card-border bg-card-bg p-6 backdrop-blur-xl">
      <div className="mb-6 flex flex-col gap-4 md:flex-row md:items-end md:justify-between">
        <div>
          <h2 className="chakra-petch text-2xl font-bold text-white">
            Construction Milestones
          </h2>
        </div>
        <div className="text-right text-sm text-gray-300">
          <p>
            {completedCount} of {items.length} complete
          </p>
          <p className="text-primary">{progress}% progress</p>
        </div>
      </div>

      <div className="mb-6 h-2 overflow-hidden rounded-full bg-[#0C0C0D]">
        <div
          className="h-full rounded-full bg-primary transition-all"
          style={{ width: `${progress}%` }}
        />
      </div>

      <ul className="space-y-3">
        {items.map((item) => (
          <li
            key={item.id}
            className="flex items-center justify-between gap-4 rounded-xl border border-card-border bg-[#0C0C0D]/45 px-4 py-3"
          >
            <span
              className={`text-sm capitalize ${
                item.completed ? 'text-gray-100' : 'text-gray-400'
              }`}
            >
              {item.label}
            </span>
            <input
              type="checkbox"
              checked={item.completed}
              aria-label={`Mark ${item.label} complete`}
              className="h-5 w-5 accent-primary"
              onChange={(event) => {
                const completed = event.target.checked;
                setItems((currentItems) =>
                  currentItems.map((currentItem) =>
                    currentItem.id === item.id
                      ? { ...currentItem, completed }
                      : currentItem
                  )
                );
              }}
            />
          </li>
        ))}
      </ul>
    </section>
  );
}

